package dev.industrialtechnology.client;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.InputEvent;import cpw.mods.fml.client.registry.*;import net.minecraft.client.Minecraft;import net.minecraft.client.settings.KeyBinding;import net.minecraft.client.renderer.entity.RenderSnowball;import org.lwjgl.input.Keyboard;import dev.industrialtechnology.accessories.*;import dev.industrialtechnology.core.IndustrialTechnology;
public final class AccessoryInput {
 private final KeyBinding charge=key("pe.key.charge","key.industrialtech.accessory_charge",Keyboard.KEY_V),fire=key("pe.key.fire_projectile","key.industrialtech.accessory_fire",Keyboard.KEY_R);
 private static KeyBinding key(String original,String ours,int code){for(KeyBinding binding:Minecraft.getMinecraft().gameSettings.keyBindings)if(binding.getKeyDescription().equals(original))return binding;KeyBinding result=new KeyBinding(ours,code,"key.categories.industrialtech");ClientRegistry.registerKeyBinding(result);return result;}
 public AccessoryInput(){RenderingRegistry.registerEntityRenderingHandler(EntityLensProjectile.class,new RenderSnowball(AccessoryRegistry.projectileIcon));RenderingRegistry.registerEntityRenderingHandler(EntityLootBall.class,new RenderSnowball(AccessoryRegistry.lootIcon));}
 @SubscribeEvent public void key(InputEvent.KeyInputEvent e){Minecraft mc=Minecraft.getMinecraft();if(mc.currentScreen!=null||mc.thePlayer==null||mc.thePlayer.getHeldItem()==null||!(mc.thePlayer.getHeldItem().getItem() instanceof ItemCatalyst)||!Keyboard.getEventKeyState()||Keyboard.isRepeatEvent())return;int key=Keyboard.getEventKey();if(key==charge.getKeyCode())IndustrialTechnology.network.sendToServer(new AccessoryCommand(0,mc.thePlayer.inventory.currentItem));else if(key==fire.getKeyCode())IndustrialTechnology.network.sendToServer(new AccessoryCommand(1,mc.thePlayer.inventory.currentItem));}
}
